inputs = ['fi', 'ucwj', 'xav', 'jvaihj', 'jaxxxj']
outputs = ['fi', 'ucwja', 'xav', 'javaihja', 'yxxxja']

print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"  {i}: '{inp}' -> '{out}'")
    if inp != out:
        # Find positions where they differ
        min_len = min(len(inp), len(out))
        diff_positions = []
        for j in range(min_len):
            if inp[j] != out[j]:
                diff_positions.append((j, inp[j], out[j]))

        if len(out) > len(inp):
            # Extra characters at the end
            extra_chars = out[len(inp):]
            print(f"    Extra chars at end: '{extra_chars}'")
        elif len(inp) > len(out):
            # Missing characters at the end  
            missing_chars = inp[len(out):]
            print(f"    Missing chars at end: '{missing_chars}'")

        if diff_positions:
            print(f"    Differences: {diff_positions}")

